import * as React from "react";
import type { HeadFC, PageProps } from "gatsby";
import { graphql } from "gatsby";
import { GatsbyImage, getImage, type IGatsbyImageData } from "gatsby-plugin-image";
import { useI18next, useTranslation } from "gatsby-plugin-react-i18next";
import  Link  from "../components/AppLink";
import CaseStudyProofGrid, {
  type CaseStudyProofItem,
  type CaseStudyProofLabels,
} from "../components/CaseStudyProofGrid";
import Layout from "../components/Layout";
import SEO from "../components/seo";
import I18nHeadProvider from "../components/I18nHeadProvider";
import type {
  I18nPageContext,
  LocaleQueryData,
} from "../components/I18nHeadProvider";
import data from "../data/data.json";
import images from "../images";
import type { Company } from "../interfaces";
import { useEffect } from "react";
import {
  buildBreadcrumbListSchema,
  buildFAQPageSchema,
  buildItemListSchema,
  localizeSitePath,
} from "../utils/structuredData";
import { trackCtaClick } from "../utils/analytics";
import { getCaseStudyProofSource } from "../utils/caseStudyProof";
import {
  getCaseStudyPrimaryServicePath,
  getServiceKeyFromPath,
} from "../utils/journeyLinks";

const info: Company = data[0];

type PortfolioPageData = {
  allFile?: {
    nodes: Array<{
      name: string;
      childImageSharp?: {
        gatsbyImageData: IGatsbyImageData;
      } | null;
    }>;
  };
};

type Project = {
  title: string;
  link: string;
  image?: string;
};

type FaqItem = {
  q: string;
  a: string;
};

function slugify(input: string) {
  return input
    .toLowerCase()
    .trim()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

const PortfolioPage: React.FC<PageProps<PortfolioPageData>> = ({ data }) => {
  const { t } = useTranslation();

  useEffect(() => {
    document.body.style.backgroundImage = `url(${images.bg.src})`;
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundRepeat = "no-repeat";

    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundRepeat = "";
    };
  }, []);

  const projects = (info?.homePage?.portfolio || []) as Project[];
  const imageLookup = React.useMemo(
    () =>
      new Map(
        (data.allFile?.nodes || [])
          .map((node) => {
            const image = node.childImageSharp?.gatsbyImageData
              ? getImage(node.childImageSharp.gatsbyImageData)
              : undefined;

            return image ? [node.name, image] : null;
          })
          .filter(
            (
              entry
            ): entry is [string, IGatsbyImageData] => Array.isArray(entry)
          )
      ),
    [data.allFile?.nodes]
  );
  const caseStudySlugsRaw = t("caseStudies.featuredSlugs", {
    returnObjects: true,
    defaultValue: [],
  }) as unknown;
  const caseStudySlugs = Array.isArray(caseStudySlugsRaw) ? caseStudySlugsRaw : [];
  const proofLabels = t("proofBlocks.labels", {
    returnObjects: true,
  }) as CaseStudyProofLabels;
  const proofCtaLabel = t("proofBlocks.ctaLabel") as string;
  const chesterCourtProof = getCaseStudyProofSource(t, "chester-court");
  const reefCleaningProof = getCaseStudyProofSource(t, "reef-cleaning-company");
  const envirogunProof = getCaseStudyProofSource(t, "envirogun");
  const bridgeProofItems: CaseStudyProofItem[] = [
    {
      client: chesterCourtProof.client,
      businessType: chesterCourtProof.businessType,
      problem:
        chesterCourtProof.challenges[1] || chesterCourtProof.challenges[0] || "",
      intervention:
        chesterCourtProof.interventions[1] ||
        chesterCourtProof.interventions[0] ||
        "",
      result:
        chesterCourtProof.results[0] ||
        chesterCourtProof.metrics[1]?.value ||
        "",
      href: chesterCourtProof.href,
      ctaLabel: proofCtaLabel,
    },
    {
      client: reefCleaningProof.client,
      businessType: reefCleaningProof.businessType,
      problem:
        reefCleaningProof.challenges[1] || reefCleaningProof.challenges[0] || "",
      intervention:
        reefCleaningProof.interventions[0] ||
        reefCleaningProof.interventions[1] ||
        "",
      result:
        reefCleaningProof.results[2] ||
        reefCleaningProof.metrics[0]?.value ||
        "",
      href: reefCleaningProof.href,
      ctaLabel: proofCtaLabel,
    },
    {
      client: envirogunProof.client,
      businessType: envirogunProof.businessType,
      problem: envirogunProof.challenges[0] || "",
      intervention:
        envirogunProof.interventions[1] ||
        envirogunProof.interventions[0] ||
        "",
      result:
        envirogunProof.results[2] ||
        envirogunProof.metrics[1]?.value ||
        "",
      href: envirogunProof.href,
      ctaLabel: proofCtaLabel,
    },
  ].filter(
    (item) =>
      item.client &&
      item.businessType &&
      item.problem &&
      item.intervention &&
      item.result
  );

  // Selecciona “featured” por título (puedes ajustar cuando quieras)
  const featuredSlugs = ["reef-cleaning-company", "envirogun", "chester-court"];
  const featured = projects.filter((p) => featuredSlugs.includes(slugify(p.title)));
  const rest = projects.filter((p) => !featuredSlugs.includes(slugify(p.title)));

  const whatsappHref = info.whatsapp;

  return (
    <Layout data={info}>
      {/* HERO */}
      <section className="pt-10 pb-6 sm:pt-14 sm:pb-10">
        <div className={styles.container}>
          <div className="text-center">
            <h1 className="text-3xl sm:text-5xl poppins-bold text-light mx-auto max-w-5xl">
              {t("portfolio.hero.title")}
            </h1>
            <p className="mt-4 text-lg sm:text-2xl poppins-regular text-light/90 mx-auto max-w-4xl">
              {t("portfolio.hero.subtitle")}
            </p>

            <div className="mx-auto mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                to="/services/"
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
                onClick={() => {
                  void trackCtaClick({
                    cta_name: "portfolio_primary_services",
                    cta_location: "portfolio_hero",
                    destination: "/services/",
                    destination_type: "internal",
                  });
                }}
              >
                {t("portfolio.cta.primary")}
              </Link>

              <a
                href={whatsappHref}
                target="_blank"
                rel="noreferrer"
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-dark font-semibold text-center"
                onClick={() => {
                  void trackCtaClick({
                    cta_name: "portfolio_secondary_contact",
                    cta_location: "portfolio_hero",
                    destination: whatsappHref,
                    destination_type: "whatsapp",
                  });
                }}
              >
                {t("portfolio.cta.secondary")}
              </a>
            </div>

            <p className="mt-6 text-sm text-light/70 mx-auto max-w-4xl">
              {t("portfolio.hero.note")}
            </p>
          </div>
        </div>
      </section>

      {/* INTRO (SEO copy + internal links) */}
      <section className="py-8 sm:py-10">
        <div className={styles.container}>
          <div className={`${styles.card} mx-auto max-w-4xl`}>
            <h2 className="text-xl sm:text-2xl font-semibold text-light/90">
              {t("portfolio.intro.title")}
            </h2>
            <p className="mt-3 text-sm sm:text-base text-light/75 leading-relaxed">
              {t("portfolio.intro.p1")}
            </p>
            <p className="mt-3 text-sm sm:text-base text-light/75 leading-relaxed">
              {t("portfolio.intro.p2")}
            </p>

            <div className="mt-6 flex flex-wrap items-center justify-center gap-2">
              <Link to="/services/web-design-development/" className="rounded-full border border-black/10 bg-purplesemilight px-4 py-2 text-sm text-dark/85 font-medium hover:bg-secondary hover:text-light">
                {t("portfolio.links.web")}
              </Link>
              <Link to="/services/seo/" className="rounded-full border border-black/10 bg-purplesemilight px-4 py-2 text-sm text-dark/85 font-medium hover:bg-secondary hover:text-light">
                {t("portfolio.links.seo")}
              </Link>
              <Link to="/services/maintenance/" className="rounded-full border border-black/10 bg-purplesemilight px-4 py-2 text-sm text-dark/85 font-medium hover:bg-secondary hover:text-light">
                {t("portfolio.links.maintenance")}
              </Link>
              <Link to="/services/analytics/" className="rounded-full border border-black/10 bg-purplesemilight px-4 py-2 text-sm text-dark/85 font-medium hover:bg-secondary hover:text-light">
                {t("portfolio.links.analytics")}
              </Link>
            </div>
          </div>
        </div>
      </section>

      <CaseStudyProofGrid
        title={t("portfolio.bridgeProof.title") as string}
        subtitle={t("portfolio.bridgeProof.subtitle") as string}
        labels={proofLabels}
        items={bridgeProofItems}
      />

      {/* FEATURED */}
      {featured.length > 0 ? (
        <section className="py-10 sm:py-14">
          <div className={styles.container}>
            <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
              {t("portfolio.featured.title")}
            </h2>
            <p className="mt-4 text-center text-sm sm:text-base text-light/70 mx-auto max-w-4xl">
              {t("portfolio.featured.subtitle")}
            </p>

            <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-4">
              {featured.map((p) => {
                const slug = slugify(p.title);
                const summaryKey = `portfolio.projects.${slug}.summary`;
                const servicesKey = `portfolio.projects.${slug}.services`;
                const hasCaseStudy = caseStudySlugs.includes(slug);
                const caseStudyPath = `/portfolio/case-studies/${slug}/`;

                const summary = t(summaryKey, { defaultValue: "" }) as string;
                const services = t(servicesKey, { defaultValue: "" }) as string;
                const primaryServicePath = hasCaseStudy
                  ? getCaseStudyPrimaryServicePath(slug)
                  : undefined;
                const primaryServiceKey = getServiceKeyFromPath(primaryServicePath);
                const primaryServiceLabel = primaryServiceKey
                  ? (t(`menu.services.${primaryServiceKey}.nav`) as string)
                  : "";

                const imageKey = p.image as keyof typeof images | undefined;
                const img = imageKey ? images[imageKey] : undefined;
                const optimizedImage = p.image ? imageLookup.get(p.image) : undefined;

                return (
                  <article key={p.link} className={styles.card}>
                    <h3 className="text-lg font-semibold text-light/90">{p.title}</h3>

                    {img?.src ? (
                      optimizedImage ? (
                        <GatsbyImage
                          image={optimizedImage}
                          alt={img.alt || p.title}
                          className="mt-4 overflow-hidden rounded-xl border border-black/10"
                        />
                      ) : (
                        <img
                          src={img.src}
                          alt={img.alt || p.title}
                          className="mt-4 w-full h-auto rounded-xl border border-black/10"
                          loading="lazy"
                          decoding="async"
                        />
                      )
                    ) : null}

                    {summary ? (
                      <p className="mt-4 text-sm sm:text-base text-light/75 leading-relaxed">
                        {summary}
                      </p>
                    ) : null}

                    {services ? (
                      <p className="mt-3 text-sm text-light/60">
                        <span className="font-semibold text-light/70">{t("portfolio.labels.services")}</span>{" "}
                        {services}
                      </p>
                    ) : null}

                    <div className="mt-6 flex items-center justify-between gap-3">
                      <a
                        href={p.link}
                        target="_blank"
                        rel="noreferrer"
                        className="rounded-full bg-secondary px-4 py-2 text-light text-sm text-center"
                        onClick={() => {
                          void trackCtaClick({
                            cta_name: `portfolio_visit_${slug}`,
                            cta_location: "portfolio_featured",
                            destination: p.link,
                            destination_type: "external",
                          });
                        }}
                      >
                        {t("portfolio.buttons.visit")}
                      </a>

                      {hasCaseStudy ? (
                        <div className="flex flex-wrap justify-end gap-3">
                          {primaryServicePath && primaryServiceLabel ? (
                            <Link
                              to={primaryServicePath}
                              className="rounded-full border border-white/15 bg-white/10 px-4 py-2 text-light text-sm text-center"
                            >
                              {t("portfolio.buttons.relatedService", {
                                service: primaryServiceLabel,
                              })}
                            </Link>
                          ) : null}
                          <Link
                            to={caseStudyPath}
                            className="rounded-full bg-purplesemilight px-4 py-2 text-dark font-semibold text-sm text-center"
                            onClick={() => {
                              void trackCtaClick({
                                cta_name: `portfolio_case_study_${slug}`,
                                cta_location: "portfolio_featured",
                                destination: caseStudyPath,
                                destination_type: "internal",
                              });
                            }}
                          >
                            {t("portfolio.featured.caseStudy")}
                          </Link>
                        </div>
                      ) : (
                        <span className="text-sm text-light/55">
                          {t("portfolio.featured.comingSoon")}
                        </span>
                      )}
                    </div>
                  </article>
                );
              })}
            </div>
          </div>
        </section>
      ) : null}

      {/* ALL PROJECTS */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
            {t("portfolio.all.title")}
          </h2>
          <p className="mt-4 text-center text-sm sm:text-base text-light/70 mx-auto max-w-4xl">
            {t("portfolio.all.subtitle")}
          </p>

          <div className="mt-8 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {projects.map((p) => {
              const imageKey = p.image as keyof typeof images | undefined;
              const img = imageKey ? images[imageKey] : undefined;
              const optimizedImage = p.image ? imageLookup.get(p.image) : undefined;

              return (
                <a
                  key={p.link}
                  href={p.link}
                  target="_blank"
                  rel="noreferrer"
                  className="group rounded-2xl border border-black/10 bg-purplesemilight p-5 shadow-sm hover:bg-secondary transition"
                  onClick={() => {
                    void trackCtaClick({
                      cta_name: `portfolio_grid_${slugify(p.title)}`,
                      cta_location: "portfolio_grid",
                      destination: p.link,
                      destination_type: "external",
                    });
                  }}
                >
                  <div className="flex items-start justify-between gap-3">
                    <h3 className="text-base font-semibold text-dark group-hover:text-light group-hover:underline">
                      {p.title}
                    </h3>
                    <span className="text-sm text-dark/55 group-hover:text-light/70">↗</span>
                  </div>

                  {img?.src ? (
                    optimizedImage ? (
                      <GatsbyImage
                        image={optimizedImage}
                        alt={img.alt || p.title}
                        className="mt-4 overflow-hidden rounded-xl border border-black/10"
                      />
                    ) : (
                      <img
                        src={img.src}
                        alt={img.alt || p.title}
                        className="mt-4 w-full h-auto rounded-xl border border-black/10"
                        loading="lazy"
                        decoding="async"
                      />
                    )
                  ) : null}

                  <div className="mt-4 text-sm text-dark/70 group-hover:text-light/70">
                    {t("portfolio.all.cardHint")}
                  </div>
                </a>
              );
            })}
          </div>

          <div className="mt-10 text-center">
            <p className="text-sm text-light/60 mx-auto max-w-4xl">
              {t("portfolio.all.note")}
            </p>
          </div>
        </div>
      </section>

      {/* FAQ */}
      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <div className="mx-auto max-w-4xl">
            <h2 className="text-2xl sm:text-4xl text-center poppins-regular text-verde">
              {t("portfolio.faq.title")}
            </h2>

            <div className="mt-8 space-y-3">
              {(t("portfolio.faq.items", { returnObjects: true }) as Array<{ q: string; a: string }>).map(
                (x, idx) => (
                  <details key={`${x.q}-${idx}`} className={styles.card}>
                    <summary className="cursor-pointer text-sm sm:text-base font-semibold text-light/90">
                      {x.q}
                    </summary>
                    <p className="mt-3 text-sm sm:text-base text-light/70 leading-relaxed">
                      {x.a}
                    </p>
                  </details>
                )
              )}
            </div>

            <div className="mt-10 flex flex-col sm:flex-row items-center justify-center gap-3">
              <Link
                to="/contact/"
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
                onClick={() => {
                  void trackCtaClick({
                    cta_name: "portfolio_final_contact",
                    cta_location: "portfolio_final_cta",
                    destination: "/contact/",
                    destination_type: "internal",
                  });
                }}
              >
                {t("portfolio.finalCta.primary")}
              </Link>
              <a
                href={whatsappHref}
                target="_blank"
                rel="noreferrer"
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-dark font-semibold text-center"
                onClick={() => {
                  void trackCtaClick({
                    cta_name: "portfolio_final_email",
                    cta_location: "portfolio_final_cta",
                    destination: whatsappHref,
                    destination_type: "whatsapp",
                  });
                }}
              >
                {t("portfolio.finalCta.secondary")}
              </a>
            </div>
          </div>
        </div>
      </section>
    </Layout>
  );
};

export const Head: HeadFC<LocaleQueryData, I18nPageContext> = ({
  data,
  pageContext,
}) => (
  <I18nHeadProvider data={data} pageContext={pageContext}>
    <PortfolioHeadContent />
  </I18nHeadProvider>
);

const PortfolioHeadContent: React.FC = () => {
  const { t } = useTranslation();
  const { language, defaultLanguage } = useI18next();

  const faq = t("portfolio.faq.items", {
    returnObjects: true,
    defaultValue: [],
  }) as FaqItem[];

  const featuredSlugs = t("caseStudies.featuredSlugs", {
    returnObjects: true,
    defaultValue: [],
  }) as string[];

  const localizedPortfolioPath = localizeSitePath(
    "/portfolio/",
    language,
    defaultLanguage
  );

  const breadcrumbSchema = buildBreadcrumbListSchema(info.url, [
    {
      name: t("menu.home") as string,
      path: localizeSitePath("/", language, defaultLanguage),
    },
    {
      name: t("menu.portfolio") as string,
      path: localizedPortfolioPath,
    },
  ]);

  const caseStudyItemList = buildItemListSchema(
    info.url,
    Array.isArray(featuredSlugs)
      ? featuredSlugs.map((slug) => ({
          name:
            (t(`caseStudies.items.${slug}.name`, { defaultValue: slug }) as string) ||
            slug,
          path: localizeSitePath(
            `/portfolio/case-studies/${slug}/`,
            language,
            defaultLanguage
          ),
        }))
      : []
  );

  const faqSchema = buildFAQPageSchema(faq);
  const additionalSchemas = [
    breadcrumbSchema,
    caseStudyItemList,
    faqSchema,
  ].filter(Boolean) as object[];

  return (
    <SEO
      data={info}
      titleKey="portfolio.metaTitle"
      descriptionKey="portfolio.metaDescription"
      pathname="/portfolio/"
      schemaType="ProfessionalService"
      pageSchemaType="CollectionPage"
      additionalSchemas={additionalSchemas.length ? additionalSchemas : undefined}
    />
  );
};

export default PortfolioPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
    allFile(
      filter: {
        sourceInstanceName: { eq: "images" }
        relativeDirectory: { eq: "portfolio" }
      }
    ) {
      nodes {
        name
        childImageSharp {
          gatsbyImageData(
            width: 720
            layout: CONSTRAINED
            placeholder: BLURRED
            formats: [AUTO, WEBP, AVIF]
          )
        }
      }
    }
  }
`;

const styles = {
  sectionWrapper:
    "border-2 w-full sm:w-[1024px] mx-auto rounded-xl p-2 sm:p-8 mt-8 bg-darkBg/50",
  labelTitle: "text-2xl sm:text-4xl text-center poppins-regular text-verde",
  container: "mx-auto w-full max-w-6xl px-4 sm:px-6",
  card: "rounded-2xl border border-black/10 bg-primary/70 p-5 shadow-sm supports-[backdrop-filter]:bg-purplesemilight/40 supports-[backdrop-filter]:backdrop-blur text-light",
  cardTitle: "text-base sm:text-lg font-semibold text-light/90",
  cardText: "mt-3 text-sm sm:text-base text-light/70 leading-relaxed",
};
